import { test, expect } from "bun:test";
test("toThrow none", () => { expect(() => {}).toThrow(); });
test("toThrow msg", () => { expect(() => { throw new Error("boom"); }).toThrow("bang"); });
test("toThrow re", () => { expect(() => { throw new Error("boom"); }).toThrow(/bang/); });
test("toThrow cls", () => { expect(() => { throw new TypeError("boom"); }).toThrow(RangeError); });
test("toThrow err", () => { expect(() => { throw new Error("boom"); }).toThrow(new Error("bang")); });
test("not.toThrow", () => { expect(() => { throw new Error("boom"); }).not.toThrow(); });
test("not.toThrow msg", () => { expect(() => { throw new Error("boom"); }).not.toThrow("bo"); });
test("toThrow did not throw msg", () => { expect(() => 1).toThrow("x"); });
test("toThrow non-error", () => { expect(() => { throw 42; }).toThrow("x"); });
test("toThrow asym", () => { expect(() => { throw new Error("boom"); }).toThrow(expect.objectContaining({ message: "x" })); });
test("not.toThrow cls", () => { expect(() => { throw new TypeError("boom"); }).not.toThrow(TypeError); });
test("not.toMatch", () => { expect("hello").not.toMatch("ell"); });
test("not.toContain", () => { expect([1, 2]).not.toContain(2); });
test("not.toHaveLength", () => { expect("ab").not.toHaveLength(2); });
test("not.gt", () => { expect(3).not.toBeGreaterThan(2); });
test("not.toHaveProperty", () => { expect({ a: 1 }).not.toHaveProperty("a"); });
test("toEqual map", () => { expect(new Map([["a", 1]])).toEqual(new Map([["a", 2]])); });
test("toEqual class", () => { class Foo { constructor() { this.x = 1; } } expect(new Foo()).toEqual({ x: 2 }); });
test("toEqual long", () => { expect(Array.from({ length: 400 }, (_, i) => i)).toEqual(Array.from({ length: 400 }, (_, i) => (i === 200 ? -1 : i))); });
